popular_posts_upscale.javascript:
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('.PopularPosts img').forEach(img => {
    let novaSrc = img.src.replace(/\/s[0-9]+(\-c)?\//, '/s600/');
    novaSrc = novaSrc.replace(/\=s[0-9]+(\-c)?/, '=s600');
    novaSrc = novaSrc.replace(/\/w[0-9]+\-h[0-9]+[^\/]+\//, '/s600/');
    img.src = novaSrc;
  });
});

animate_up.js_observer:
const elementosAnimaveis = document.querySelectorAll('.card-post-grid, aside .widget');
elementosAnimaveis.forEach((el, index) => {
  el.classList.add('animate-up');
  el.style.transitionDelay = `${(index % 3) * 0.1}s`;
  scrollObserver.observe(el);
});
